from typing import List

def min_value(n: int, arr: List[int]) -> int:
    dp = [sys.maxsize] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            if j <= arr[i-1]:
                dp[i] = min(dp[i], dp[j] + arr[i-1])
    return dp[n]

